// ---- from Code/GameEngine/Source/GameClient/GUI/TextOnFrameTransitionUpdate.cpp

void TextOnFrameTransition::update(Int frame)
{
	if (frame < m_startFrame || frame > m_endFrame)
	{
		return;
	}
	if (frame == m_startFrame)
	{
		if (!m_isForward && m_win)
		{
			m_win->winHide(TRUE);
			m_isFinished = TRUE;
		}
	}
	else if (frame == m_endFrame)
	{
		if (m_isForward && m_win)
		{
			m_win->winHide(FALSE);
			m_isFinished = TRUE;
		}
	}
}

// ---- from Code/GameEngine/Source/GameClient/GUI/TextOnFrameTransitionReverse.cpp

void TextOnFrameTransition::reverse(void)
{
	m_isFinished = FALSE;
	m_isForward = FALSE;
	if (m_win->winIsHidden())
	{
		m_isFinished = TRUE;
		m_frameLength = 0;
	}
}

